# Generated by GitHub Copilot - Oct-05-2026
def fold_text(text):
    """Normalize PT-BR lexical comparisons without changing literal transcript."""
    return "".join(character for character in unicodedata.normalize("NFD", str(text).casefold())
                   if unicodedata.category(character) != "Mn")


# Generated by GitHub Copilot - Oct-05-2026
def terms(text):
    """Remove generic discourse terms from topic/entity/editorial comparisons."""
    return {term for term in re.findall(r"\b\w+\b", fold_text(text)) if len(term) >= 3 and term not in GENERIC_TERMS}


