def finite_score(value):
    """Keep missing evidence null and reject booleans/non-finite subjective scores."""
    return float(value) if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and 0 <= value <= 1 else None


# Generated by GitHub Copilot - Oct-05-2026
def normalize_context(row):
    """Project legacy free-form context into a strict enum without inventing certainty."""
    explicit = row.get("context_requirement")
    legacy = row.get("context_required")
    value = fold_text(legacy).strip() if legacy is not None else ""
    if explicit in CONTEXT_REQUIREMENTS:
        requirement = explicit
    elif legacy is False or value in {"none", "nao", "nenhum", "nenhuma", "sem contexto", "nao precisa", "nao necessario"}:
        requirement = "none"
    elif legacy is True or value in {"required", "necessario", "obrigatorio"}:
        requirement = "required"
    elif value in {"helpful", "util", "ajuda"}:
        requirement = "helpful"
    elif value and value not in {"null", "none", "unresolved"}:
        requirement = "required"
    else:
        requirement = "unresolved"
    reason = row.get("context_reason")
    if reason is None and isinstance(legacy, str) and value not in {"", "null", *CONTEXT_REQUIREMENTS, "nao", "nenhum", "nenhuma"}:
        reason = legacy
    result = {"context_requirement": requirement,
              "context_reason": reason[:1500] if isinstance(reason, str) and reason.strip() else None,
              "context_required": None if requirement == "unresolved" else requirement,
              "legacy_context_required": legacy}
    for key in ("context_seconds_before", "context_seconds_after"):
        value = row.get(key)
        result[key] = float(value) if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and 0 <= value <= 3600 else (0.0 if requirement == "none" else None)
    return result


# Generated by GitHub Copilot - Oct-05-2026
def require_pt_br(texts):
    """Reject clearly English metadata; lexical detection is not language accuracy."""
    vocabulary = re.findall(r"\b[a-z]+\b", fold_text(" ".join(str(text or "") for text in texts)))
    english = {"the", "this", "that", "with", "which", "because", "about", "are", "was", "were", "and", "their", "they", "would", "from"}
    portuguese = {"que", "com", "porque", "sobre", "uma", "para", "das", "dos", "fala", "historia", "trecho", "momento", "contexto", "nao"}
    english_hits = [word for word in vocabulary if word in english]
    portuguese_hits = [word for word in vocabulary if word in portuguese]
    if len(set(english_hits)) >= 3 and len(english_hits) > 2 * len(portuguese_hits):
        raise ValueError("language_mismatch: metadata deve ser PT-BR; detector lexical nao calibrado.")
    return True


# Generated by GitHub Copilot - Oct-05-2026
def classify_content(text, evidence_segment_ids=None):
    """Use explicit commercial/housekeeping cues, never civil identity or brand alone."""
    normalized = fold_text(text)
    signals = {
        "price": r"\br\s*\$|\breais\b|\bpor apenas\b",
        "discount": r"\b(desconto|cupom|promocao|oferta|parcelamento)\b",
        "store": r"\b(loja|compre|comprar|venda|produto|produtos)\b",
        "sales_cta": r"\b(compre|aproveite|garanta|peca agora|ligue|acesse a loja|venha conferir)\b",
        "contact": r"\b(telefone|whatsapp|endereco|rua|avenida)\b",
        "sponsor": r"\b(patrocinador|patrocinio|oferecimento|oferecido por)\b",
    }
    reasons = [key for key, pattern in signals.items() if re.search(pattern, normalized)]
    strong = len(reasons) >= 2 and bool(set(reasons) & {"sales_cta", "discount", "sponsor"})
    if "sponsor" in reasons:
        content_type, score = "sponsor_read", .8
    elif strong:
        content_type, score = "advertisement", min(1.0, .45 + .12 * len(reasons))
    elif re.search(r"\b(inscreva|se inscreve|compartilhe|deixe o like|segue o canal)\b", normalized):
        content_type, score = "housekeeping", 0.0
    elif re.search(r"\b(bem vindos|boa noite pessoal|ate o proximo programa|encerramos)\b", normalized):
        content_type, score = "intro_outro", 0.0
    elif reasons:
        content_type, score = "uncertain", .15 * len(reasons)
    else:
        content_type, score = "editorial_content", 0.0
    return {"content_type": content_type, "commercial_score": score, "reasons": reasons,
            "evidence_segment_ids": list(evidence_segment_ids or []),
            "classifier_method": "pt_br_lexical_multicue_heuristic", "needs_review": bool(reasons),
            "confidence_is_calibrated": False}


# Generated by GitHub Copilot - Oct-05-2026
def normalize_moment(moment):
    """Normalize control fields and preserve actual model/source provenance."""
    row = {**moment, **normalize_context(moment)}
    if row.get("standalone_class") not in {"excellent", "good", "needs_context", "poor"}:
        row["standalone_class"] = "needs_context"
    row["needs_review"] = row.get("needs_review") if isinstance(row.get("needs_review"), bool) else True
    row["metadata_locale"] = "pt-BR"
    row["confidence_method"] = "subjective_llm_judgment" if row.get("method") == "ollama" else "lexical_heuristic"
    row["commercial_classification"] = classify_content(row.get("text", ""), row.get("evidence_segment_ids", []))
    row.update({key: row["commercial_classification"][key] for key in ("content_type", "commercial_score")})
    return row


# Generated by GitHub Copilot - Oct-05-2026
def topic_hierarchy(topics, segments):
    """Merge adjacent equivalent topics and keep the primary theme evidence-qualified."""
    by_id = {segment["segment_id"]: segment for segment in segments}
    merged = []
    merge_count = 0
    for original in topics:
        topic = {**original, **normalize_context(original), "metadata_locale": "pt-BR"}
        topic["merged_topic_ids"] = [topic["topic_id"]]
        ids = topic.get("evidence_segment_ids", [])
        literal = " ".join(by_id[segment_id].get("text", "") for segment_id in ids if segment_id in by_id)
        topic.update({key: value for key, value in classify_content(literal, ids).items() if key in ("content_type", "commercial_score")})
        previous = merged[-1] if merged else None
        lexical = terms(topic.get("topic", ""))
        before = terms(previous.get("topic", "")) if previous else set()
        equivalent = bool(lexical and before and len(lexical & before) / len(lexical | before) >= .8)
        if previous and equivalent and topic["start"] - previous["end"] <= 3 and previous["content_type"] == topic["content_type"]:
            previous["end"] = topic["end"]
            previous["evidence_segment_ids"] = list(dict.fromkeys(previous["evidence_segment_ids"] + ids))
            previous["merged_topic_ids"].extend(topic["merged_topic_ids"])
            merge_count += 1
        else:
            merged.append(topic)
    sections=[]
    for topic in merged:
        previous=sections[-1] if sections else None
        lexical=terms(topic.get('topic',''))
        preceding=terms(previous['title']) if previous else set()
        related=bool(lexical and preceding and len(lexical & preceding)/len(lexical | preceding)>=.35)
        if (previous and related and previous['content_type']==topic['content_type'] and
                topic['start']-previous['end']<=3 and topic['end']-previous['start']<=900):
            previous['end']=topic['end']
            previous['topic_ids'].append(topic['topic_id'])
            previous['evidence_segment_ids']=list(dict.fromkeys(previous['evidence_segment_ids']+topic.get('evidence_segment_ids',[])))
        else:
            sections.append({'section_id':f'SECTION_{len(sections):04}','start':topic['start'],'end':topic['end'],
                             'title':topic['topic'],'topic_ids':[topic['topic_id']],
                             'evidence_segment_ids':list(topic.get('evidence_segment_ids',[])),
                             'content_type':topic['content_type'],'method':'adjacent_topic_lexical_relatedness_grouping','needs_review':True})
    qualified = [topic for topic in merged if topic.get("method") == "ollama" and topic["content_type"] not in COMMERCIAL_TYPES
                 and terms(topic.get("topic", "")) and topic.get("evidence_segment_ids")]
    qualified.sort(key=lambda topic: (-(topic["end"] - topic["start"]), topic["topic_id"]))
    primary = {key: qualified[0].get(key) for key in ("topic_id", "topic", "summary", "evidence_segment_ids", "method")} if qualified else None
    covered = {segment_id for topic in merged for segment_id in topic.get("evidence_segment_ids", [])}
    count = len(merged)
    quality = {"topic_count": count, "merged_topic_count": merge_count,
               "heuristic_topic_fraction": sum(topic.get("method") != "ollama" for topic in merged) / count if count else None,
               "LLM_topic_fraction": sum(topic.get("method") == "ollama" for topic in merged) / count if count else None,
               "uncovered_segment_fraction": len(set(by_id) - covered) / len(by_id) if by_id else None,
               "commercial_topic_fraction": sum(topic["content_type"] in COMMERCIAL_TYPES for topic in merged) / count if count else None,
               "primary_theme_status": "grounded_model_topic_requires_review" if primary else "unresolved_no_qualified_theme",
               "duplicate_topic_similarity_warnings": []}
    return merged, sections, primary, [topic["topic_id"] for topic in qualified[1:]], quality


