def optimize_boundaries(moment, segments, cfg=None, story=None):
    """Choose source sentence/story boundaries; never fabricate times to meet duration."""
    cfg = cfg or {}
    by_id = {segment["segment_id"]: index for index, segment in enumerate(segments)}
    indices = [by_id[segment_id] for segment_id in moment.get("evidence_segment_ids", []) if segment_id in by_id]
    if not indices:
        indices = [index for index, segment in enumerate(segments)
                   if segment["start"] < moment["end"] and moment["start"] < segment["end"]]
    if not indices:
        return {"ideal_start": moment["start"], "ideal_end": moment["end"],
                "alternate_starts": [], "alternate_ends": [], "boundary_reason": "unresolved_no_segment_evidence",
                "context_added_before": 0.0, "context_added_after": 0.0, "duration_suitability_score": None}
    first, last = min(indices), max(indices)
    core_start, core_end = segments[first]["start"], segments[last]["end"]
    opening = fold_text(segments[first].get("text", "")).strip()
    context = normalize_context(moment)["context_requirement"]
    reference = bool(re.match(r"^(ele|ela|eles|elas|isso|aquilo|esse|essa|mas|porque|entao|ai)\b", opening))
    if first and (reference or context in {"required", "helpful"}) and core_start - segments[first - 1]["start"] <= 30:
        first -= 1
    if story and story["start"] <= core_start and core_end <= story["end"] and story["end"] - story["start"] <= cfg.get("candidate_hard_max_seconds", 180):
        story_indices = [index for index, segment in enumerate(segments) if story["start"] <= segment["start"] and segment["end"] <= story["end"]]
        if story_indices:
            first, last = min(first, min(story_indices)), max(last, max(story_indices))
    if last + 1 < len(segments) and not segments[last].get("text", "").rstrip().endswith((".", "?", "!")):
        if segments[last + 1]["end"] - core_end <= 30:
            last += 1
    start, end = segments[first]["start"], segments[last]["end"]
    duration = end - start
    preferred_min, preferred_max = cfg.get("candidate_preferred_min_seconds", 30), cfg.get("candidate_preferred_max_seconds", 90)
    hard_max, minimum = cfg.get("candidate_hard_max_seconds", 180), cfg.get("candidate_min_seconds", 8)
    suitability = (1.0 if preferred_min <= duration <= preferred_max else .6 if minimum <= duration <= hard_max else .1)
    return {"ideal_start": start, "ideal_end": end,
            "alternate_starts": sorted({core_start, start}), "alternate_ends": sorted({core_end, end}),
            "boundary_reason": "grounded_sentence_reference_and_story_completion",
            "context_added_before": max(0.0, core_start - start), "context_added_after": max(0.0, end - core_end),
            "clean_opening": not reference or start < core_start,
            "clean_ending": segments[last].get("text", "").rstrip().endswith((".", "?", "!")),
            "duration_suitability_score": suitability, "duration_requires_review": duration > hard_max or duration < minimum,
            "duration_soft_max_exceeded": duration > cfg.get("candidate_soft_max_seconds", 120),
            "boundary_segment_ids": [segment["segment_id"] for segment in segments[first:last + 1]]}


