def rank_candidate(candidate, cfg=None):
    """Expose explicit weighted editorial utility and penalties, never viral probability."""
    cfg = cfg or {}
    components = {"hook": finite_score(candidate.get("hook_score")),
                  "standalone_clarity": finite_score(candidate.get("standalone_score")),
                  "clean_opening": float(candidate["clean_opening"]) if isinstance(candidate.get("clean_opening"), bool) else None,
                  "clean_ending": float(candidate["clean_ending"]) if isinstance(candidate.get("clean_ending"), bool) else None,
                  "story_completeness": finite_score(candidate.get("story_completeness")),
                  "qa_completeness": 1.0 if candidate.get("question_answer_complete") else None,
                  "information_density": finite_score(candidate.get("information_score")),
                  "curiosity": finite_score(candidate.get("curiosity_score")), "emotion": finite_score(candidate.get("emotion_score")),
                  "surprise": finite_score(candidate.get("surprise_score")), "controversy": finite_score(candidate.get("conflict_score")),
                  "humor": finite_score(candidate.get("humor_score")), "visual_viability": finite_score(candidate.get("visual_score")),
                  "audio_quality": finite_score(candidate.get("audio_quality")),
                  "duration_suitability": finite_score(candidate.get("duration_suitability_score"))}
    weights = cfg.get("ranking_weights", DEFAULT_WEIGHTS)
    observed_weight = sum(weight for key, weight in weights.items() if components.get(key) is not None)
    raw = sum(components[key] * weight for key, weight in weights.items() if components.get(key) is not None) / observed_weight if observed_weight else None
    commercial = candidate.get("content_type") in COMMERCIAL_TYPES and not cfg.get("allow_commercial_candidates", False)
    context = candidate.get("context_requirement", "unresolved")
    penalties = {"commercial": cfg.get("commercial_penalty", .5) if commercial else 0.0,
                 "context_dependency": .1 if context == "required" else 0.0,
                 "unresolved_evidence": .05 if context == "unresolved" else 0.0,
                 "duplicate": 0.0}
    final = max(0.0, min(1.0, raw - sum(penalties.values()))) if raw is not None else None
    return {**candidate, "editorial_score_raw": raw, "score_components": components, "penalties": penalties,
            "score_weights": weights, "observed_weight": observed_weight,
            "editorial_score_final": final, "editorial_score": final, "ranking_version": "4.2.0",
            "score_method": "explicit_weighted_observed_utility_not_probability",
            "default_shortlist_eligible": not commercial}


# Generated by GitHub Copilot - Oct-05-2026
def _equivalent(left, right):
    """Require temporal and editorial equivalence for non-exact deduplication."""
    left_start, left_end = left["ideal_start"], left["ideal_end"]
    right_start, right_end = right["ideal_start"], right["ideal_end"]
    intersection = max(0.0, min(left_end, right_end) - max(left_start, right_start))
    if not intersection:
        return False, False
    exact = abs(left_start-right_start)<=1e-6 and abs(left_end-right_end)<=1e-6
    if exact:
        return True, True
    union = max(left_end, right_end) - min(left_start, right_start)
    shorter = min(left_end - left_start, right_end - right_start)
    overlap = intersection / shorter if shorter > 0 else 0.0
    left_ids, right_ids = set(left.get("evidence_segment_ids", [])), set(right.get("evidence_segment_ids", []))
    evidence_share = len(left_ids & right_ids) / max(1, min(len(left_ids), len(right_ids)))
    left_terms = terms(left.get("core_moment", {}).get("text") or left.get("text", ""))
    right_terms = terms(right.get("core_moment", {}).get("text") or right.get("text", ""))
    lexical_share = len(left_terms & right_terms) / max(1, len(left_terms | right_terms))
    return (intersection / union >= .8 or overlap >= .8) and (evidence_share >= .8 or lexical_share >= .85), False


